 56→func (a *openCodeAgent) Bootstrap() error {
 57→	// opencode has first-run DB migration + node_modules resolution that
 58→	// races with parallel test execution (upstream issue #6935).
 59→	// Run a trivial prompt to force full initialization before tests.
 60→	for i := range 3 {
 61→		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
 62→		cmd := exec.CommandContext(ctx, a.Binary(), "run", "--model", a.model, "say hi")
 63→		cmd.Env = os.Environ()
 64→		out, err := cmd.CombinedOutput()
 65→		cancel()
 66→		if err == nil {
 67→			return nil
 68→		}
 69→		if i < 2 {
 70→			fmt.Fprintf(os.Stderr, "opencode warmup attempt %d failed: %s\n%s\n", i+1, err, out)
 71→			time.Sleep(5 * time.Second)
 72→		}
 73→	}
 74→	// Non-fatal: warmup failure shouldn't block tests entirely.
 75→	fmt.Fprintln(os.Stderr, "opencode warmup failed after 3 attempts, proceeding anyway")
 76→	return nil
 77→}
