 36→type Agent interface {
 37→	Name() string
 38→	// Binary returns the CLI binary name (e.g. "claude", "gemini").
 39→	Binary() string
 40→	EntireAgent() string
 41→	PromptPattern() string
 42→	// TimeoutMultiplier returns a factor applied to per-test timeouts.
 43→	// Slower agents (e.g. Gemini) return values > 1.
 44→	TimeoutMultiplier() float64
 45→	RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error)
 46→	StartSession(ctx context.Context, dir string) (Session, error)
 47→	// Bootstrap performs one-time CI setup (auth config, warmup, etc.).
 48→	// Called before any tests run. Implementations should be idempotent.
 49→	Bootstrap() error
 50→	// IsTransientError returns true if the error from RunPrompt looks like
 51→	// a transient API failure (e.g. 500, rate limit, network error) that
 52→	// is worth retrying.
 53→	IsTransientError(out Output, err error) bool
 54→}
 55→
 56→type Session interface {
 57→	Send(input string) error
 58→	WaitFor(pattern string, timeout time.Duration) (string, error)
 59→	Capture() string
