import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

// isolatedDataDir creates a temp directory for XDG_DATA_HOME so each opencode
// invocation gets its own SQLite database. Without this, parallel tests share
// ~/.local/share/opencode/ and hit "database is locked" errors.
func isolatedDataDir() (string, func(), error) {
	dir, err := os.MkdirTemp("", "opencode-data-*")
	if err != nil {
		return "", nil, err
	}
	// Copy credentials from default data dir so auth works.
	home, _ := os.UserHomeDir()
	defaultData := filepath.Join(home, ".local", "share", "opencode")
	if src := filepath.Join(defaultData, "credentials.json"); fileExists(src) {
		dst := filepath.Join(dir, "opencode")
		_ = os.MkdirAll(dst, 0o755)
		if data, err := os.ReadFile(src); err == nil {
			_ = os.WriteFile(filepath.Join(dst, "credentials.json"), data, 0o644)
		}
	}
	return dir, func() { _ = os.RemoveAll(dir) }, nil
}

func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

